css:
/* muse:allow pure-black: 阅读正文使用近墨黑 #14171C，与暖纸白形成真实纸张反差，是阅读面形式语言
   muse:allow dark-canvas: 夜间长时阅读场景下，有意外壳用深墨蓝而非默认浅底，见 direction 说明 */

:root{
  /* 骨架 · 深墨蓝 */
  --ink-950:#0C1018;
  --ink-900:#101523;
  --ink-850:#151B2B;
  --ink-800:#1B2334;
  --ink-700:#26304A;

  /* 阅读面 · 暖纸白 */
  --paper:#F6F2E9;
  --paper-line:#D9D2C3;
  --paper-ink:#14171C;
  --paper-ink-3:#676A73;

  /* 墨底上的字 */
  --on-ink:#E7E4DC;
  --on-ink-2:#A2A8B8;
  --on-ink-3:#7C8398;
  --hair:rgba(232,236,248,.10);
  --hair-strong:rgba(232,236,248,.20);

  /* 杏色 · 只用于运行态与焦点 */
  --apricot:#E2A268;
  --apricot-deep:#B8722F;
  --apricot-wash:rgba(226,162,104,.12);
  --apricot-line:rgba(226,162,104,.38);

  --bad:#DB8C7E;

  --r-card:8px;
  --r-tag:4px;
  --r-pill:999px;

  --rail-w:284px;
  --session-w:268px;
  --gutter:24px;

  --ease:cubic-bezier(.16,1,.3,1);

  --font-ui:'PingFang SC','Hiragino Sans GB','Microsoft YaHei','Noto Sans SC',system-ui,-apple-system,'Segoe UI',sans-serif;
  --font-read:'Songti SC','Noto Serif SC','Source Han Serif SC','SimSun',Georgia,serif;
  --font-mono:ui-monospace,'SF Mono','JetBrains Mono','Roboto Mono',Menlo,Consolas,monospace;
}

*,*::before,*::after{box-sizing:border-box}

html{-webkit-text-size-adjust:100%}
body{
  margin:0;min-height:100dvh;
  background:var(--ink-950);color:var(--on-ink);
  font-family:var(--font-ui);font-size:14px;line-height:1.55;
  -webkit-font-smoothing:antialiased;
}

.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}

.skip-link{
  position:fixed;top:8px;left:8px;z-index:60;
  transform:translateY(-160%);
  background:var(--paper);color:var(--paper-ink);
  padding:10px 16px;border-radius:var(--r-tag);
  font-weight:600;text-decoration:none;
  transition:transform .18s var(--ease);
}
.skip-link:focus-visible{transform:translateY(0)}

:focus-visible{outline:2px solid var(--apricot);outline-offset:2px;border-radius:3px}
.leaf:focus,.shelf p:focus,.session p:focus{outline:none}

/* ================= 布局骨架 ================= */
.app{
  display:grid;grid-template-columns:var(--rail-w) minmax(0,1fr);
  min-height:100dvh;
  background:
    radial-gradient(120% 80% at 78% -10%, rgba(226,162,104,.055), transparent 60%),
    var(--ink-950);
}

/* ================= 侧栏 ================= */
.rail{
  display:flex;flex-direction:column;gap:20px;
  padding:20px 0 16px;
  background:var(--ink-900);border-right:1px solid var(--hair);
  min-height:100dvh;position:sticky;top:0;max-height:100dvh;overflow:hidden;
}
.rail-top{padding:0 16px;display:flex;flex-direction:column;gap:20px}

.brand{display:flex;align-items:center;gap:10px}
.brand-mark{
  width:34px;height:34px;flex:none;display:grid;place-items:center;
  color:var(--apricot);background:var(--apricot-wash);
  border:1px solid var(--apricot-line);border-radius:var(--r-card);
}
.brand-mark svg{width:19px;height:19px;stroke-linejoin:round;stroke-linecap:round}
.brand-text{display:flex;flex-direction:column;line-height:1.25;min-width:0}
.brand-name{font-size:17px;font-weight:700;letter-spacing:.14em;color:var(--on-ink)}
.brand-sub{font-size:12px;color:var(--on-ink-3);letter-spacing:.04em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rail-close{
  margin-left:auto;display:none;width:40px;height:40px;flex:none;
  align-items:center;justify-content:center;
  background:transparent;border:1px solid var(--hair);
  border-radius:var(--r-tag);color:var(--on-ink-2);cursor:pointer;
}
.rail-close svg{width:18px;height:18px}

.nav{display:flex;flex-direction:column;gap:2px;border-top:1px solid var(--hair);padding-top:14px}
.nav-item{
  display:block;width:100%;text-align:left;min-height:40px;
  padding:9px 12px;background:transparent;border:0;border-radius:6px;
  color:var(--on-ink-2);font-family:inherit;font-size:14px;letter-spacing:.04em;cursor:pointer;
  transition:background .18s var(--ease), color .18s var(--ease);
}
.nav-item:hover{background:rgba(232,236,248,.045);color:var(--on-ink)}
.nav-item.is-current{
  background:rgba(232,236,248,.07);color:var(--on-ink);font-weight:600;
  box-shadow:inset 0 0 0 1px var(--hair);
}

/* ---------- 书架 ---------- */
.shelf{display:flex;flex-direction:column;gap:14px;flex:1;min-height:0;padding:0 16px}
.shelf-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.shelf-title{margin:0;font-size:12px;font-weight:600;letter-spacing:.16em;color:var(--on-ink-3)}
.shelf-count{font-family:var(--font-mono);font-size:12px;color:var(--on-ink-3)}
.shelf-tools{display:flex;flex-direction:column;gap:10px}

.search-field{position:relative;display:flex;align-items:center}
.search-icon{position:absolute;left:10px;width:15px;height:15px;color:var(--on-ink-3);pointer-events:none}
#shelfSearch{
  width:100%;min-height:40px;padding:9px 34px 9px 32px;
  background:var(--ink-850);border:1px solid var(--hair);border-radius:6px;
  color:var(--on-ink);font-family:inherit;font-size:13px;
  transition:border-color .18s var(--ease), background .18s var(--ease);
}
#shelfSearch::placeholder{color:var(--on-ink-3)}
#shelfSearch:hover{border-color:var(--hair-strong)}
#shelfSearch:focus{outline:none}
#shelfSearch:focus-visible{outline:2px solid var(--apricot);outline-offset:2px;background:var(--ink-800)}
.search-clear{
  position:absolute;right:4px;width:32px;height:32px;display:grid;place-items:center;
  background:transparent;border:0;border-radius:4px;color:var(--on-ink-3);cursor:pointer;
}
.search-clear:hover{color:var(--on-ink)}
.search-clear svg{width:14px;height:14px}

.filters{display:flex;flex-wrap:wrap;gap:6px}
.chip{
  min-height:32px;padding:5px 12px;
  background:transparent;border:1px solid var(--hair);border-radius:var(--r-pill);
  color:var(--on-ink-2);font-family:inherit;font-size:12.5px;letter-spacing:.04em;cursor:pointer;
  transition:background .18s var(--ease), color .18s var(--ease), border-color .18s var(--ease);
}
.chip:hover{border-color:var(--hair-strong);color:var(--on-ink)}
.chip[aria-pressed="true"]{background:var(--apricot-wash);border-color:var(--apricot-line);color:var(--apricot);font-weight:600}

/* ---------- 书列 ---------- */
.book-list{
  list-style:none;margin:0;padding:0 0 8px;
  overflow-y:auto;flex:1;min-height:0;
  display:flex;flex-direction:column;gap:2px;
  scrollbar-width:thin;scrollbar-color:var(--ink-700) transparent;
}
.book-list::-webkit-scrollbar{width:6px}
.book-list::-webkit-scrollbar-thumb{background:var(--ink-700);border-radius:3px}

.book{
  width:100%;text-align:left;
  display:grid;grid-template-columns:40px minmax(0,1fr);
  gap:12px;align-items:center;
  padding:9px 10px;min-height:64px;
  background:transparent;border:0;border-radius:6px;
  cursor:pointer;position:relative;
  transition:background .18s var(--ease);
}
.book:hover{background:rgba(232,236,248,.05)}
.book[aria-current="true"]{
  background:rgba(226,162,104,.09);
  box-shadow:inset 0 0 0 1px var(--apricot-line);
}
.book[aria-current="true"]::before{
  content:"";position:absolute;left:0;top:12px;bottom:12px;
  width:2px;border-radius:2px;background:var(--apricot);
}
.spine{
  width:40px;height:54px;border-radius:3px 5px 5px 3px;
  display:flex;align-items:center;justify-content:center;
  background:var(--spine-bg);
  box-shadow:0 1px 3px rgba(0,0,0,.45), inset 2px 0 0 rgba(0,0,0,.22), inset 9px 0 0 rgba(255,255,255,.05);
  overflow:hidden;flex:none;
}
.spine b{
  writing-mode:vertical-rl;text-orientation:upright;
  font-size:12px;font-weight:600;letter-spacing:.1em;
  color:var(--spine-ink,#F6F2E9);line-height:1;font-style:normal;
}
.book-text{display:flex;flex-direction:column;gap:3px;min-width:0}
.book-name{font-size:13.5px;font-weight:600;color:var(--on-ink);line-height:1.35;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.book[aria-current="true"] .book-name{color:var(--apricot)}
.book-auth{font-size:12px;color:var(--on-ink-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.book-state{font-family:var(--font-mono);font-size:11px;letter-spacing:.08em;color:var(--on-ink-3)}
mark{background:var(--apricot-wash);color:var(--apricot);border-radius:2px;padding:0 1px}

.shelf-empty{margin:0;padding:22px 4px;font-size:13px;color:var(--on-ink-2);line-height:1.7;border-top:1px solid var(--hair)}
.shelf-empty strong{color:var(--on-ink);font-weight:600;display:block;margin-bottom:6px;font-size:13.5px}
.shelf-empty button{
  margin-top:10px;min-height:34px;background:transparent;
  border:1px solid var(--apricot-line);color:var(--apricot);border-radius:var(--r-pill);
  padding:6px 14px;font-family:inherit;font-size:12.5px;cursor:pointer;
}
.rail-foot{margin:0;padding:14px 16px 0;border-top:1px solid var(--hair);font-size:11.5px;color:var(--on-ink-3);line-height:1.6}

/* ================= 主区 ================= */
.stage{display:flex;flex-direction:column;min-width:0;min-height:100dvh}

.topbar{
  display:flex;align-items:center;gap:12px;
  padding:14px var(--gutter);
  border-bottom:1px solid var(--hair);
  background:linear-gradient(180deg,rgba(12,16,24,.92),rgba(12,16,24,.6));
  backdrop-filter:blur(10px);
  position:sticky;top:0;z-index:20;
}
.rail-open{
  display:none;width:44px;height:44px;flex:none;
  align-items:center;justify-content:center;
  background:transparent;border:1px solid var(--hair);
  border-radius:var(--r-tag);color:var(--on-ink-2);cursor:pointer;
}
.rail-open svg{width:19px;height:19px}
.crumb{margin:0;font-size:13px;color:var(--on-ink-2);display:flex;align-items:center;gap:8px;min-width:0}
.crumb-dim{color:var(--on-ink-3)}
.crumb-sep{color:var(--on-ink-3)}
#crumbBook{color:var(--on-ink);font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.session-flag{
  margin:0 0 0 auto;flex:none;font-family:var(--font-mono);font-size:11px;letter-spacing:.1em;
  color:var(--on-ink-3);border:1px solid var(--hair);border-radius:var(--r-pill);padding:4px 10px;
}

.panes{
  display:grid;grid-template-columns:minmax(0,1fr) var(--session-w);
  gap:var(--gutter);padding:var(--gutter);
  flex:1;align-items:start;max-width:1320px;
}

/* ---------- 阅读面 ---------- */
.reading{display:flex;flex-direction:column;gap:20px;min-width:0}

.leaf{
  background:var(--paper);color:var(--paper-ink);
  border-radius:var(--r-card);padding:40px 52px 32px;
  box-shadow:0 24px 48px -28px rgba(0,0,0,.7);
  position:relative;
}
.leaf::after{content:"";position:absolute;inset:0;border-radius:var(--r-card);pointer-events:none;box-shadow:inset 0 0 0 1px rgba(20,23,28,.06)}

.leaf-head{display:flex;align-items:flex-start;gap:20px;padding-bottom:22px;border-bottom:1px solid var(--paper-line)}
.leaf-meta{min-width:0;flex:1}
.leaf-kicker{margin:0 0 10px;font-family:var(--font-mono);font-size:11px;letter-spacing:.16em;color:var(--paper-ink-3)}
.leaf-title{margin:0;font-family:var(--font-read);font-size:32px;font-weight:600;line-height:1.2;letter-spacing:.01em;color:var(--paper-ink)}
.leaf-author{margin:10px 0 0;font-size:13px;color:var(--paper-ink-3);letter-spacing:.05em}
.leaf-status{
  flex:none;font-family:var(--font-mono);font-size:11px;letter-spacing:.1em;
  color:var(--apricot-deep);background:rgba(184,114,47,.1);
  border:1px solid rgba(184,114,47,.3);border-radius:var(--r-pill);padding:4px 11px;
}

.leaf-chapter{margin:28px 0 20px;display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}
.chapter-no{font-family:var(--font-mono);font-size:11px;letter-spacing:.16em;color:var(--paper-ink-3)}
.chapter-title{margin:0;font-family:var(--font-read);font-size:20px;font-weight:600;line-height:1.4;letter-spacing:.02em;color:var(--paper-ink)}

.prose{max-width:33em}
.prose p{margin:0 0 1.05em;font-family:var(--font-read);font-size:17px;line-height:1.85;letter-spacing:.015em;color:var(--paper-ink)}
.prose p:first-child::first-letter{float:left;font-size:44px;line-height:.86;padding:4px 8px 0 0;color:var(--apricot-deep);font-weight:600}

.leaf-foot{
  margin-top:24px;padding-top:14px;border-top:1px solid var(--paper-line);
  display:flex;align-items:center;gap:10px;flex-wrap:wrap;
  font-family:var(--font-mono);font-size:11.5px;letter-spacing:.05em;color:var(--paper-ink-3);
}
.leaf-foot-sep{opacity:.6}

/* ---------- 札记 ---------- */
.note{
  background:var(--ink-900);border:1px solid var(--hair);border-radius:var(--r-card);
  padding:20px;display:flex;flex-direction:column;gap:12px;
}
.note-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap}
.note-label{font-size:13.5px;font-weight:600;color:var(--on-ink);letter-spacing:.05em}
.note-hint{font-size:11.5px;color:var(--on-ink-3);font-family:var(--font-mono)}
#noteInput{
  width:100%;resize:vertical;min-height:104px;padding:12px 14px;
  background:var(--ink-850);border:1px solid var(--hair);border-radius:6px;
  color:var(--on-ink);font-family:var(--font-ui);font-size:14px;line-height:1.7;
  transition:border-color .18s var(--ease);
}
#noteInput::placeholder{color:var(--on-ink-3)}
#noteInput:hover{border-color:var(--hair-strong)}
#noteInput:focus{outline:none}
#noteInput:focus-visible{outline:2px solid var(--apricot);outline-offset:1px;border-color:var(--apricot-line)}
#noteInput[aria-invalid="true"]{border-color:var(--bad)}

.note-error{
  margin:0;padding:9px 12px;background:rgba(219,140,126,.1);
  border:1px solid rgba(219,140,126,.35);border-radius:6px;
  color:var(--bad);font-size:12.5px;line-height:1.6;
}
.note-error button{background:transparent;border:0;padding:0;color:var(--on-ink);text-decoration:underline;cursor:pointer;font-family:inherit;font-size:12.5px}
.note-foot{display:flex;align-items:center;gap:12px}
.note-count{font-family:var(--font-mono);font-size:11.5px;color:var(--on-ink-3);margin-right:auto}

/* ---------- 按钮 ---------- */
.btn{
  min-height:40px;padding:9px 18px;border-radius:var(--r-pill);
  font-family:inherit;font-size:13.5px;font-weight:600;letter-spacing:.04em;
  cursor:pointer;border:1px solid transparent;
  transition:background .18s var(--ease), color .18s var(--ease), border-color .18s var(--ease), transform .12s var(--ease);
}
.btn:active{transform:translateY(1px)}
.btn-primary{background:var(--apricot);color:#241708;border-color:var(--apricot)}
.btn-primary:hover{background:#EDB27C}
.btn-primary.is-running{background:transparent;color:var(--apricot);border-color:var(--apricot-line)}
.btn-quiet{background:transparent;color:var(--on-ink-2);border-color:var(--hair)}
.btn-quiet:hover:not(:disabled){border-color:var(--hair-strong);color:var(--on-ink)}
.btn:disabled{opacity:.4;cursor:not-allowed}

/* ---------- 书封（纯 CSS 排印 + SVG 几何） ---------- */
.cover{
  aspect-ratio:2/3;width:100%;max-width:224px;margin:0 auto;
  border-radius:5px;overflow:hidden;
  box-shadow:0 20px 36px -22px rgba(0,0,0,.85);
  display:block;position:relative;
}
.cover-face{
  position:absolute;inset:0;display:flex;flex-direction:column;
  padding:22px 20px 20px;background:var(--spine-bg);
}
.cover-face::before{
  content:"";position:absolute;top:0;bottom:0;left:0;width:11px;
  background:linear-gradient(90deg,rgba(0,0,0,.42),rgba(0,0,0,0));
  pointer-events:none;
}
.cover-face::after{
  content:"";position:absolute;top:0;bottom:0;left:11px;width:1px;
  background:rgba(255,255,255,.14);pointer-events:none;
}
.cover-rule{display:block;height:1px;width:26px;background:currentColor;opacity:.5;margin-bottom:14px;flex:none;position:relative;z-index:1}
.cover-title{
  position:relative;z-index:1;margin-top:auto;margin-bottom:12px;
  font-family:var(--font-read);font-weight:600;
  writing-mode:vertical-rl;text-orientation:upright;
  letter-spacing:.14em;max-height:60%;align-self:flex-start;
  text-shadow:0 1px 0 rgba(0,0,0,.2);
}
.cover-title-sm{font-size:20px;line-height:1.06}
.cover-title-lg{font-size:28px;line-height:1.06}
.cover-author{position:relative;z-index:1;font-size:12px;letter-spacing:.2em;font-family:var(--font-ui);margin-bottom:10px}
.cover-imprint{position:relative;z-index:1;font-family:var(--font-mono);font-size:9.5px;letter-spacing:.1em;opacity:.74;line-height:1.4}
.cover-caption{margin:0;font-size:12px;color:var(--on-ink-3);letter-spacing:.03em;text-align:center;line-height:1.6}

/* ---------- 计时栏 ---------- */
.session{display:flex;flex-direction:column;gap:18px;position:sticky;top:84px;min-width:0}

.timer{
  border:1px solid var(--hair);border-radius:var(--r-card);
  background:var(--ink-900);padding:20px;
  display:flex;flex-direction:column;gap:10px;
}
.timer-label{margin:0;font-size:11.5px;letter-spacing:.16em;font-family:var(--font-mono);color:var(--on-ink-3)}
.timer-value{
  margin:0;font-family:var(--font-mono);font-size:38px;font-weight:400;
  line-height:1.1;letter-spacing:.02em;color:var(--on-ink);
  font-variant-numeric:tabular-nums;
}
.timer.is-running .timer-value{color:var(--apricot)}
.timer.is-running{border-color:var(--apricot-line);background:rgba(226,162,104,.055)}
.timer-note{margin:0;font-size:12.5px;line-height:1.6;color:var(--on-ink-3);min-height:2.6em}
.timer-note.is-live{color:var(--apricot)}
.timer-actions{display:flex;gap:8px;margin-top:4px;flex-wrap:wrap}
.timer-actions .btn{flex:1 1 auto;min-width:0}

.dock-toggle{
  display:none;width:100%;min-height:52px;
  align-items:center;justify-content:space-between;gap:12px;
  padding:12px 16px;background:var(--ink-850);border:1px solid var(--hair);
  border-radius:var(--r-card);color:var(--on-ink);
  font-family:inherit;font-size:13.5px;cursor:pointer;
}
.dock-toggle-text{font-family:var(--font-mono);font-size:12.5px;letter-spacing:.04em}
.dock-chevron svg{width:18px;height:18px;color:var(--on-ink-3);display:block}
.dock-toggle[aria-expanded="false"] .dock-chevron svg{transform:rotate(180deg)}

.scrim{position:fixed;inset:0;z-index:30;background:rgba(6,9,15,.62);backdrop-filter:blur(2px)}

/* ================= 响应式 ================= */
@media (max-width:1180px){
  :root{--session-w:238px;--gutter:20px}
  .leaf{padding:34px 40px 28px}
}

@media (max-width:1023px){
  .app{grid-template-columns:1fr}
  .rail{
    position:fixed;z-index:40;top:0;left:0;bottom:0;width:308px;max-height:100dvh;
    transform:translateX(-102%);transition:transform .28s var(--ease);
    box-shadow:24px 0 48px -24px rgba(0,0,0,.8);
  }
  .rail.is-open{transform:translateX(0)}
  .rail-close{display:flex}
  .rail-open{display:flex}
  .panes{grid-template-columns:1fr;padding:20px}
  .session{position:static;flex-direction:row;align-items:flex-start;gap:20px;flex-wrap:wrap}
  .session .cover{width:150px;flex:none;margin:0}
  .cover-caption{display:none}
  .timer{flex:1;min-width:230px}
}

@media (max-width:640px){
  .topbar{padding:12px 16px;gap:10px}
  .session-flag{display:none}
  .panes{padding:16px;gap:16px}

  .leaf{padding:24px 18px 20px;border-radius:6px}
  .leaf-head{flex-direction:column;gap:12px;padding-bottom:18px}
  .leaf-title{font-size:26px}
  .leaf-status{align-self:flex-start}
  .leaf-chapter{margin:22px 0 16px}
  .chapter-title{font-size:18px}
  .prose{max-width:none}
  .prose p{font-size:16.5px;line-height:1.9;letter-spacing:.02em}
  .prose p:first-child::first-letter{font-size:38px}

  .note{padding:16px}
  #noteInput{font-size:16px;min-height:112px}
  .note-foot{flex-direction:column;align-items:stretch;gap:10px}
  .note-count{margin-right:0}
  .note-foot .btn{width:100%;min-height:46px}

  /* 计时收进底坞 */
  .session{
    flex-direction:column;position:fixed;left:0;right:0;bottom:0;z-index:35;
    background:var(--ink-900);border-top:1px solid var(--hair-strong);
    border-radius:14px 14px 0 0;
    padding:12px 16px calc(16px + env(safe-area-inset-bottom));
    gap:14px;
    transform:translateY(calc(100% - 76px));
    transition:transform .3s var(--ease);
    box-shadow:0 -18px 40px -24px rgba(0,0,0,.9);
    max-height:82dvh;overflow-y:auto;
  }
  .session.is-open{transform:translateY(0)}
  .session .cover{width:100%;max-width:124px;align-self:center}
  .dock-toggle{display:flex;order:-1}
  .session .btn{min-height:48px;width:100%}
  .timer-actions{flex-direction:column}
  .reading{padding-bottom:96px}

  .chip{min-height:36px;padding:6px 14px;font-size:13px}
  .book{min-height:64px;padding:10px}
}

@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{transition-duration:.01ms !important;animation-duration:.01ms !important}
}

