(function () {
  'use strict';

  /* ---------- 概念示例数据：全部虚构，无云端，不使用 localStorage ---------- */
  var BOOKS = [
    {
      id: 'slow-testimony',
      title: '慢的证词',
      spineLabel: '慢的',
      author: '沈砚舟',
      status: 'reading',
      chapterNo: '第三章',
      chapterTitle: '钟表店打烊之后',
      progress: 46,
      pages: '172 / 372 页',
      spineBg: '#1F2A44',
      spineInk: '#F6F2E9',
      cover: { bg: '#1F2A44', ink: '#F6F2E9', accent: '#E2A268', kind: 'arc' },
      prose: [
        '打烊之后，钟表店里同时走着三百种时间。每一只都慢一点或快一点，谁也没有错，只是没有人愿意承认自己的那只才是准的。',
        '他把怀表翻过来，看见表壳内侧刻着一行几乎磨平的字。那是他父亲留下的，写的是「不必着急」。他小时候觉得这是懒人的借口，现在却读成了一句技术说明——指针走得太快，齿轮会先磨坏。',
        '街上最后一家店铺也在拉闸。铁门滑下来的声音像一句被拖长的叹息。他忽然想，今天什么也没做成，只是把四十七只表从抽屉里拿出来，擦干净，又放回去。这算不算一种工作。'
      ]
    },
    {
      id: 'sixteen-streets',
      title: '深夜的十六条街',
      spineLabel: '深夜',
      author: '苏未晞',
      status: 'reading',
      chapterNo: '第七条街',
      chapterTitle: '没有招牌的面馆',
      progress: 28,
      pages: '96 / 342 页',
      spineBg: '#7A3B2E',
      spineInk: '#F6F2E9',
      cover: { bg: '#7A3B2E', ink: '#F6F2E9', accent: '#F0D9B5', kind: 'grid' },
      prose: [
        '第七条街没有名字，本地人靠一家面馆认路。面馆也没有招牌，只在门框上钉了一块被油烟熏成深褐色的木板，上面什么也没写。',
        '老板娘下面条时不看锅，看人。她说一个人走进来的脚步声，能听出他今天是想吃饱，还是只想坐一会儿。前者下三两，后者下二两，多一筷子，汤上会多飘两片青菜。',
        '我在那里坐过很多次。有一次坐到打烊，她收完最后一副碗筷，才慢慢说：这条街上的人都在赶路，只有你不是。我说我在等一个人。她说，那也算赶路，只是你在站着赶。'
      ]
    },
    {
      id: 'rain-chronicle',
      title: '雨的编年史',
      spineLabel: '雨的',
      author: '顾行野',
      status: 'wish',
      chapterNo: '序章',
      chapterTitle: '记录者不在雨中',
      progress: 4,
      pages: '28 / 410 页',
      spineBg: '#2E4A46',
      spineInk: '#F6F2E9',
      cover: { bg: '#2E4A46', ink: '#F6F2E9', accent: '#D6C9A8', kind: 'lines' },
      prose: [
        '下雨的时候，记录的人往往站在屋檐下。这不是怯懦，而是所有观测都需要的距离——你得先不被淋湿，才写得清雨的形状。',
        '这部编年史里没有一场雨是用来抒情的。每一场都被记下起止时刻、当时的温度、雨滴落在什么材质上。落铁皮棚是一种声音，落荷叶是另一种，落在一封没寄出的信上，是第三种。',
        '所以这本书记的不是雨，是声音如何被时间挑选。'
      ]
    },
    {
      id: 'paper-and-its-age',
      title: '纸与它的时代',
      spineLabel: '纸与',
      author: '林昭白',
      status: 'done',
      chapterNo: '终章',
      chapterTitle: '最后一页纸',
      progress: 100,
      pages: '386 / 386 页',
      spineBg: '#3E3A34',
      spineInk: '#F6F2E9',
      cover: { bg: '#3E3A34', ink: '#F6F2E9', accent: '#E2A268', kind: 'stack' },
      prose: [
        '纸不是承载文字的容器，它自己会老。泛黄不是损坏，是一本书终于长出了它自己的颜色。',
        '我在一家旧书店里见过一本落款模糊的账册，纸页软得像一张张晒过太阳的旧手帕。店主说这本不可卖，因为它已经不属于任何人。',
        '一本书最后的归宿，大概是被翻到散线。那不算毁坏，那算读完。'
      ]
    }
  ];

  var STATUS_TEXT = { reading: '在读', wish: '想读', done: '已读' };
  var STATUS_ORDER = { reading: 0, wish: 1, done: 2 };

  var state = {
    books: BOOKS.map(function (b) { return Object.assign({}, b, { note: '' }); }),
    activeId: 'slow-testimony',
    filter: 'all',
    query: '',
    noteDirty: false
  };

  var timers = {};
  BOOKS.forEach(function (b) { timers[b.id] = { elapsed: 0, running: false }; });
  var timerTick = null;

  var $ = function (id) { return document.getElementById(id); };
  var bookList = $('bookList');
  var shelfEmpty = $('shelfEmpty');
  var shelfCount = $('shelfCount');
  var searchInput = $('shelfSearch');
  var searchClear = $('searchClear');
  var rail = $('rail');
  var scrim = $('scrim');
  var railOpen = $('railOpen');
  var railClose = $('railClose');
  var session = $('session');
  var dockToggle = $('dockToggle');

  function activeBook() {
    for (var i = 0; i < state.books.length; i++) {
      if (state.books[i].id === state.activeId) return state.books[i];
    }
    return state.books[0];
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function highlight(text, q) {
    var safe = esc(text);
    if (!q) return safe;
    var idx = safe.toLowerCase().indexOf(q.toLowerCase());
    if (idx === -1) return safe;
    var end = idx + q.length;
    return safe.slice(0, idx) + '<mark>' + safe.slice(idx, end) + '</mark>' + safe.slice(end);
  }

  /* ---------- 书封几何：四种 SVG 母题 ---------- */
  function coverMarkup(c) {
    var a = c.accent;
    var s = '<svg viewBox="0 0 200 300" preserveAspectRatio="none" aria-hidden="true" ' +
      'style="position:absolute;inset:0;width:100%;height:100%;display:block">';
    var body = '';
    var i, y, w;

    if (c.kind === 'arc') {
      body += '<circle cx="128" cy="196" r="60" fill="none" stroke="' + a + '" stroke-opacity=".5" stroke-width="1"/>';
      body += '<circle cx="128" cy="196" r="39" fill="none" stroke="' + a + '" stroke-opacity=".34" stroke-width="1"/>';
      body += '<path d="M128 196 V136" stroke="' + a + '" stroke-opacity=".75" stroke-width="1.6"/>';
      body += '<path d="M128 196 L173 225" stroke="' + a + '" stroke-opacity=".55" stroke-width="1.6"/>';
    } else if (c.kind === 'grid') {
      for (i = 1; i < 5; i++) {
        body += '<path d="M0 ' + (i * 60) + ' H200" stroke="' + a + '" stroke-opacity=".2" stroke-width="1"/>';
      }
      for (i = 1; i < 4; i++) {
        body += '<path d="M' + (i * 50) + ' 60 V300" stroke="' + a + '" stroke-opacity=".26" stroke-width="1"/>';
      }
      body += '<rect x="50" y="118" width="100" height="122" fill="' + a + '" fill-opacity=".13"/>';
    } else if (c.kind === 'lines') {
      for (i = 0; i < 13; i++) {
        y = 116 + i * 11;
        w = 56 - Math.abs(i - 6) * 7;
        body += '<path d="M' + (128 - w) + ' ' + y + ' H' + (128 + w) + '" stroke="' + a +
          '" stroke-opacity="' + (0.6 - i * 0.033).toFixed(2) + '" stroke-width="1.4" stroke-linecap="round"/>';
      }
      body += '<circle cx="128" cy="96" r="3" fill="' + a + '" fill-opacity=".8"/>';
    } else {
      for (i = 0; i < 5; i++) {
        body += '<rect x="' + (56 + i * 3) + '" y="' + (122 + i * 6) + '" width="' + (116 - i * 6) +
          '" height="102" fill="none" stroke="' + a + '" stroke-opacity="' +
          (0.46 - i * 0.065).toFixed(2) + '" stroke-width="1"/>';
      }
      body += '<path d="M128 122 V224" stroke="' + a + '" stroke-opacity=".5" stroke-width="1"/>';
    }
    return s + body + '</svg>';
  }

  function coverHTML(book, large) {
    var c = book.cover;
    var sizeClass = large ? 'cover-title-lg' : 'cover-title-sm';
    return '<div class="cover-face" style="--spine-bg:' + c.bg + '">' +
      coverMarkup(c) +
      '<span class="cover-rule" style="color:' + c.ink + '"></span>' +
      '<span class="cover-title ' + sizeClass + '" style="color:' + c.ink + '">' + esc(book.title) + '</span>' +
      '<span class="cover-author" style="color:' + c.accent + '">' + esc(book.author) + '</span>' +
      '<span class="cover-imprint" style="color:' + c.accent + '">拾页文库 · 概念示例</span>' +
      '</div>';
  }

  function renderCover() {
    $('cover').innerHTML = coverHTML(activeBook(), true);
  }

  /* ---------- 书架 ---------- */
  function filtered() {
    var q = state.query.trim().toLowerCase();
    return state.books.filter(function (b) {
      if (state.filter !== 'all' && b.status !== state.filter) return false;
      if (!q) return true;
      return (b.title + ' ' + b.author + ' ' + b.spineLabel).toLowerCase().indexOf(q) !== -1;
    }).sort(function (a, b) { return STATUS_ORDER[a.status] - STATUS_ORDER[b.status]; });
  }

  function renderShelf() {
    var rows = filtered();
    var q = state.query.trim();
    shelfCount.textContent = rows.length + ' 本';

    if (!rows.length) {
      bookList.innerHTML = '';
      shelfEmpty.hidden = false;
      if (state.filter !== 'all' && !q) {
        shelfEmpty.innerHTML = '<strong>这一栏还空着。</strong>' +
          '「' + esc(STATUS_TEXT[state.filter]) + '」暂时没有书。换一个筛选，或者把手上的这本读完再归来。' +
          '<br><button type="button" data-reset="filter">查看全部 ' + state.books.length + ' 本</button>';
      } else {
        shelfEmpty.innerHTML = '<strong>没有找到「' + esc(q) + '」。</strong>' +
          '试试作者名，或者只输入书名里的一个字。' +
          '<br><button type="button" data-reset="query">清除搜索</button>';
      }
      return;
    }

    shelfEmpty.hidden = true;
    bookList.innerHTML = rows.map(function (b) {
      var cur = b.id === state.activeId;
      return '<li>' +
        '<button class="book" type="button" data-id="' + b.id + '" aria-current="' + cur + '">' +
          '<span class="spine" style="--spine-bg:' + b.spineBg + ';--spine-ink:' + b.spineInk + '" aria-hidden="true">' +
            '<b>' + esc(b.spineLabel) + '</b>' +
          '</span>' +
          '<span class="book-text">' +
            '<span class="book-name">' + highlight(b.title, q) + '</span>' +
            '<span class="book-auth">' + highlight(b.author, q) + '</span>' +
            '<span class="book-state">' + STATUS_TEXT[b.status] + ' · ' + b.progress + '%</span>' +
          '</span>' +
        '</button>' +
      '</li>';
    }).join('');
  }

  /* ---------- 阅读区 ---------- */
  function renderReading() {
    var b = activeBook();
    $('crumbBook').textContent = b.title;
    $('bookKicker').textContent = '拾页文库 · 概念示例 · 非真实出版物';
    $('bookTitle').textContent = b.title;
    $('bookAuthor').textContent = b.author + '　著';
    $('bookStatus').textContent = STATUS_TEXT[b.status];
    $('chapterNo').textContent = b.chapterNo;
    $('chapterTitle').textContent = b.chapterTitle;
    $('bookProgress').textContent = '读完 ' + b.progress + '%';
    $('bookPages').textContent = b.pages;
    $('bookProse').innerHTML = b.prose.map(function (p) {
      return '<p>' + esc(p) + '</p>';
    }).join('');
    $('noteInput').value = b.note;
    state.noteDirty = false;
    updateNoteMeta();
    clearNoteError();
  }

  /* ---------- 札记 ---------- */
  function updateNoteMeta() {
    $('noteCount').textContent = $('noteInput').value.trim().length + ' 字';
    $('noteHint').textContent = state.noteDirty ? '有未保存的修改' : '仅存于本次会话';
  }

  function clearNoteError() {
    var el = $('noteError');
    el.hidden = true;
    el.innerHTML = '';
    $('noteInput').removeAttribute('aria-invalid');
  }

  function showNoteError(msg, retryLabel) {
    var el = $('noteError');
    el.hidden = false;
    $('noteInput').setAttribute('aria-invalid', 'true');
    el.innerHTML = esc(msg) + ' <button type="button" id="noteRetry">' + esc(retryLabel) + '</button>';
  }

  /* ---------- 计时 ---------- */
  function fmt(sec) {
    var m = Math.floor(sec / 60);
    var s = sec % 60;
    return (m < 10 ? '0' + m : '' + m) + ':' + (s < 10 ? '0' + s : '' + s);
  }

  function renderTimer() {
    var t = timers[state.activeId];
    var block = $('timerBlock');
    var toggle = $('timerToggle');
    var reset = $('timerReset');
    var note = $('timerNote');

    $('timerValue').textContent = fmt(t.elapsed);
    $('dockTime').textContent = fmt(t.elapsed);
    block.classList.toggle('is-running', t.running);
    toggle.classList.toggle('is-running', t.running);
    note.classList.toggle('is-live', t.running);

    if (t.running) {
      toggle.textContent = '暂停';
      toggle.setAttribute('aria-label', '暂停本次阅读计时');
      note.textContent = '记录中。不累计跨天，只算这一段的专注。';
      reset.disabled = false;
    } else if (t.elapsed > 0) {
      toggle.textContent = '继续阅读';
      toggle.setAttribute('aria-label', '继续本次阅读计时');
      note.textContent = '已停。' + fmt(t.elapsed) + ' 留在这里，重置才会清空。';
      reset.disabled = false;
    } else {
      toggle.textContent = '开始阅读';
      toggle.setAttribute('aria-label', '开始本次阅读计时');
      note.textContent = '开始计时，只记这一段。';
      reset.disabled = true;
    }
  }

  function stopTick() {
    if (timerTick !== null) { clearInterval(timerTick); timerTick = null; }
  }

  function startTick() {
    stopTick();
    timerTick = setInterval(function () {
      var t = timers[state.activeId];
      if (!t || !t.running) return;
      t.elapsed += 1;
      renderTimer();
    }, 1000);
  }

  function toggleTimer() {
    var t = timers[state.activeId];
    if (t.running) { t.running = false; stopTick(); }
    else { t.running = true; startTick(); }
    renderTimer();
  }

  function resetTimer() {
    var t = timers[state.activeId];
    t.running = false;
    t.elapsed = 0;
    stopTick();
    renderTimer();
  }

  /* ---------- 选择书籍 ---------- */
  function selectBook(id) {
    if (id === state.activeId) { closeRail(); return; }
    var prev = timers[state.activeId];
    if (prev && prev.running) { prev.running = false; stopTick(); }
    state.activeId = id;
    renderShelf();
    renderReading();
    renderCover();
    renderTimer();
    closeRail();
    var pane = $('reading-pane');
    if (pane && pane.focus) pane.focus({ preventScroll: true });
  }

  /* ---------- 抽屉 ---------- */
  function openRail() {
    rail.classList.add('is-open');
    railOpen.setAttribute('aria-expanded', 'true');
    scrim.hidden = false;
  }
  function closeRail() {
    rail.classList.remove('is-open');
    railOpen.setAttribute('aria-expanded', 'false');
    scrim.hidden = true;
  }

  /* ---------- 事件 ---------- */
  function closest(el, sel) {
    return el && el.closest ? el.closest(sel) : null;
  }

  bookList.addEventListener('click', function (e) {
    var btn = closest(e.target, '.book');
    if (btn) selectBook(btn.getAttribute('data-id'));
  });

  shelfEmpty.addEventListener('click', function (e) {
    var btn = closest(e.target, 'button[data-reset]');
    if (!btn) return;
    if (btn.getAttribute('data-reset') === 'query') {
      searchInput.value = '';
      state.query = '';
      searchClear.hidden = true;
    } else {
      state.filter = 'all';
      syncChips();
    }
    renderShelf();
  });

  var chips = Array.prototype.slice.call(document.querySelectorAll('.chip'));
  function syncChips() {
    chips.forEach(function (c) {
      c.setAttribute('aria-pressed', String(c.getAttribute('data-filter') === state.filter));
    });
  }
  chips.forEach(function (c) {
    c.addEventListener('click', function () {
      state.filter = c.getAttribute('data-filter');
      syncChips();
      renderShelf();
    });
  });

  searchInput.addEventListener('input', function () {
    state.query = searchInput.value;
    searchClear.hidden = !searchInput.value;
    renderShelf();
  });

  searchClear.addEventListener('click', function () {
    searchInput.value = '';
    state.query = '';
    searchClear.hidden = true;
    renderShelf();
    searchInput.focus();
  });

  $('noteInput').addEventListener('input', function () {
    state.noteDirty = true;
    clearNoteError();
    updateNoteMeta();
  });

  $('noteForm').addEventListener('submit', function (e) {
    e.preventDefault();
    var input = $('noteInput');
    if (input.value.length > 2000) {
      showNoteError('札记超过 2000 字，先在别处存一份，再回来删减。', '我知道了');
      input.focus();
      return;
    }
    activeBook().note = input.value;
    state.noteDirty = false;
    clearNoteError();
    updateNoteMeta();
    $('noteHint').textContent = '已保存到本次会话';
    window.setTimeout(function () {
      if (!state.noteDirty) $('noteHint').textContent = '仅存于本次会话';
    }, 2200);
  });

  $('noteError').addEventListener('click', function (e) {
    if (closest(e.target, '#noteRetry')) {
      clearNoteError();
      $('noteInput').focus();
    }
  });

  $('timerToggle').addEventListener('click', toggleTimer);
  $('timerReset').addEventListener('click', resetTimer);
  railOpen.addEventListener('click', openRail);
  railClose.addEventListener('click', closeRail);
  scrim.addEventListener('click', closeRail);

  dockToggle.addEventListener('click', function () {
    var open = session.classList.toggle('is-open');
    dockToggle.setAttribute('aria-expanded', String(open));
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
      closeRail();
      if (session.classList.contains('is-open')) {
        session.classList.remove('is-open');
        dockToggle.setAttribute('aria-expanded', 'false');
        dockToggle.focus();
      }
    }
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
      if (window.matchMedia('(max-width:1023px)').matches) openRail();
      searchInput.focus();
      e.preventDefault();
    }
  });

  window.addEventListener('pagehide', stopTick);

  /* ---------- 启动 ---------- */
  renderShelf();
  renderReading();
  renderCover();
  renderTimer();
  syncChips();
})();
